begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();


select throws_ok($$ select private.validate_form_schema('{"fields":[{"id":"c","type":"checkbox","label":"Any conditions?","sensitive":true},{"id":"d","type":"short_text","label":"More","show_if":{"field":"c","equals":true}}]}') $$, '23514', 'show_if_leaks_sensitive', 'an ordinary field cannot depend on a sensitive answer');
select lives_ok($$ select private.validate_form_schema('{"fields":[{"id":"c","type":"checkbox","label":"Any conditions?","sensitive":true},{"id":"d","type":"short_text","label":"More","sensitive":true,"show_if":{"field":"c","equals":true}}]}') $$, 'a sensitive field may');
select throws_ok($$ select private.validate_form_schema('{"fields":[{"id":"a","type":"dropdown","label":"ID","options":[{"value":"1","label":"Passport number"}]}]}') $$, '23514', 'forbidden_field', 'option labels are checked');
select is(private.is_forbidden_field_text('S.S.N.'), true, 'S.S.N.');
select is(private.is_forbidden_field_text('soc sec #'), true, 'soc sec');
select is(private.is_forbidden_field_text('Social Insurance Number'), true, 'social insurance');
select is(private.is_forbidden_field_text('Shirt size'), false, 'ordinary labels pass');

select * from finish();
rollback;
